### textWithLink: Draw text with a link annotation

Source: https://github.com/parallax/jspdf/blob/master/docs/modules_annotations.js.html

Draws text and adds a link annotation over it. Supports maxWidth to wrap text and align options (center/right) to adjust the link position. Returns the total line width of the text.

```javascript
jsPDFAPI.textWithLink = function(text, x, y, options) {
  var totalLineWidth = this.getTextWidth(text);
  var lineHeight = this.internal.getLineHeight() / this.internal.scaleFactor;
  var linkHeight, linkWidth;

  // Checking if maxWidth option is passed to determine lineWidth and number of lines for each line
  if (options.maxWidth !== undefined) {
    var { maxWidth } = options;
    linkWidth = maxWidth;
    var numOfLines = this.splitTextToSize(text, linkWidth).length;
    linkHeight = Math.ceil(lineHeight * numOfLines);
  } else {
    linkWidth = totalLineWidth;
    linkHeight = lineHeight;
  }

  this.text(text, x, y, options);

  //TODO We really need the text baseline height to do this correctly.
  // Or ability to draw text on top, bottom, center, or baseline.
  y += lineHeight * 0.2;
  //handle x position based on the align option
  if (options.align === "center") {
    x = x - totalLineWidth / 2; //since starting from center move the x position by half of text width
  }
  if (options.align === "right") {
    x = x - totalLineWidth;
  }
  this.link(x, y - lineHeight, linkWidth, linkHeight, options);
  return totalLineWidth;
};
```

--------------------------------

### textWithLink(text, x, y, options)

Source: https://github.com/parallax/jspdf/blob/master/docs/modules_annotations.js.html

Adds text to the page and creates a link annotation covering the text. Returns the width of the text/link.

```APIDOC
## textWithLink(text, x, y, options)

### Description
Adds text to the page and creates a link annotation covering the text. Returns the width of the text/link.

### Parameters
- **text** (string) - Required - The text to display.
- **x** (number) - Required - The x-coordinate of the text position.
- **y** (number) - Required - The y-coordinate of the text position.
- **options** (Object) - Required - Options for the text and link.
  - `maxWidth` (number) - Optional - Maximum width for the text; if provided, the text is split into multiple lines and the link height adjusts accordingly.
  - `align` (string) - Optional - Text alignment: 'left', 'center', or 'right'. Affects the link's x position.
  - Any other options supported by the `text` method.

### Returns
- **number** - The width of the text/link.
```

--------------------------------

### jsPDF output method implementation

Source: https://github.com/parallax/jspdf/blob/master/docs/jspdf.js.html

The `output` method of jsPDF generates the PDF document and supports various output types. It handles options as a string (filename) or object, defaults filename to 'generated.pdf', and returns different formats based on the `type` argument. For 'bloburl', it warns if URL.createObjectURL is unsupported. For 'pdfobjectnewwindow', it throws an error if not in a browser environment.

```javascript
var output = (API.output = API.__private__.output = SAFE(function output(
    type,
    options
  ) {
    options = options || {};

    if (typeof options === "string") {
      options = {
        filename: options
      };
    } else {
      options.filename = options.filename || "generated.pdf";
    }

    switch (type) {
      case undefined:
        return buildDocument();
      case "save":
        API.save(options.filename);
        break;
      case "arraybuffer":
        return getArrayBuffer(buildDocument());
      case "blob":
        return getBlob(buildDocument());
      case "bloburi":
      case "bloburl":
        // Developer is responsible of calling revokeObjectURL
        if (
          typeof globalObject.URL !== "undefined" &&
          typeof globalObject.URL.createObjectURL === "function"
        ) {
          return (
            (globalObject.URL &&
              globalObject.URL.createObjectURL(getBlob(buildDocument()))) ||
            void 0
          );
